require __DIR__.'/common.php';$job=json_decode(stream_get_contents(STDIN),true,16,JSON_THROW_ON_ERROR);try{if(($job['operation']??'')==='verify'){$uid=$job['user_id'];$n=(int)$db->run('SELECT COUNT(*) FROM m_bookings WHERE user_id=?',[$uid])->fetchColumn();$l=(int)$db->run("SELECT COUNT(*) FROM m_credit_reservations WHERE user_id=? AND state='held'",[$uid])->fetchColumn();echo json_encode(['bookings'=>$n,'holds'=>$l]);}else{$id=(new Morshed\Product\Consultations($db,$audit))->reserve($job['actor'],$job['data']);echo json_encode(['ok'=>true,'id'=>$id]);}}catch(Morshed\Core\Problem $e){echo json_encode(['ok'=>false,'code'=>$e->errorCode]);}
